import pandas as pd
rest = pd.read_csv('/app/data/restaurants/clean_restaurant_2022.csv')

def top_by_cuisine(city, cuisine, n=5):
    city_rest = rest[rest['City'].str.lower()==city.lower()].copy()
    matches = city_rest[city_rest['Cuisines'].fillna('').str.contains(cuisine, case=False, na=False)]
    matches = matches.sort_values(['Aggregate Rating','Average Cost'], ascending=[False, True])
    return matches[['Name','Cuisines','Aggregate Rating','Average Cost']].head(n)

cities=['Cleveland','Columbus','Cincinnati','Minneapolis']
for city in cities:
    print('\n==',city,'==')
    for cuisine in ['American','Mediterranean','Chinese','Italian']:
        top=top_by_cuisine(city,cuisine, n=5)
        print('\n', cuisine)
        if top.empty:
            print('  none')
        else:
            print(top.to_string(index=False))
